import { defineTool } from '@deepseek-ai/dsh-tools';

export const name = 'm0-inject-probe';
export const inject = ['tools'];   // ← 承重的那一行：ctx key，不是类名

export function apply(ctx, config = {}) {
  ctx.tools.register(defineTool({
    name: 'm0_probe',
    description: 'M0 inject probe.',
    parameters: { note: { type: 'string', description: 'ignored' } },
    output: {
      schema: { type: 'object', additionalProperties: false, properties: { summary: { type: 'string', required: true } } },
      render: (_args, value) => [{ type: 'text', text: value.summary }],
    },
    isConcurrencySafe: () => true,
    execute: async () => ({ summary: 'M0-INJECT-PROBE-ALIVE' }),
  }));
}

export default { name, inject, apply };
